CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE scans(id TEXT PRIMARY KEY,started_at TEXT NOT NULL,finished_at TEXT NOT NULL,status TEXT NOT NULL,health TEXT NOT NULL,coverage_state TEXT NOT NULL,applicable_required INTEGER NOT NULL,assessed_required INTEGER NOT NULL,unknown_required INTEGER NOT NULL);
CREATE TABLE components(scan_id TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,id TEXT NOT NULL,kind TEXT NOT NULL,implementation_family TEXT NOT NULL,implementation_version TEXT NOT NULL,display_alias TEXT NOT NULL,provenance TEXT NOT NULL,inventory_state TEXT NOT NULL,PRIMARY KEY(scan_id,id));
CREATE TABLE dependency_edges(scan_id TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,id TEXT NOT NULL,source_component_id TEXT NOT NULL,destination_component_id TEXT NOT NULL,relationship_kind TEXT NOT NULL,provenance TEXT NOT NULL,confidence TEXT NOT NULL,recorded_at TEXT NOT NULL,PRIMARY KEY(scan_id,id),FOREIGN KEY(scan_id,source_component_id) REFERENCES components(scan_id,id),FOREIGN KEY(scan_id,destination_component_id) REFERENCES components(scan_id,id));
CREATE TABLE probe_executions(id TEXT PRIMARY KEY,scan_id TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,probe_id TEXT NOT NULL,probe_version TEXT NOT NULL,outcome TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT NOT NULL,duration_ms INTEGER NOT NULL,limitation_code TEXT NOT NULL);
CREATE TABLE observations(id TEXT PRIMARY KEY,scan_id TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,probe_execution_id TEXT NOT NULL REFERENCES probe_executions(id) ON DELETE CASCADE,component_id TEXT NOT NULL,kind TEXT NOT NULL,schema_version TEXT NOT NULL,observed_at TEXT NOT NULL,capability_id TEXT NOT NULL,provider_id TEXT NOT NULL,sensitivity TEXT NOT NULL,UNIQUE(scan_id,id),FOREIGN KEY(scan_id,component_id) REFERENCES components(scan_id,id));
CREATE TABLE observation_bitcoin_rpc_transport(observation_id TEXT PRIMARY KEY REFERENCES observations(id) ON DELETE CASCADE,reached INTEGER NOT NULL CHECK(reached IN (0,1)),authentication TEXT NOT NULL CHECK(authentication IN ('accepted','rejected','unknown')),category TEXT NOT NULL);
CREATE TABLE observation_bitcoin_chain_state(observation_id TEXT PRIMARY KEY REFERENCES observations(id) ON DELETE CASCADE,blocks INTEGER NOT NULL,headers INTEGER NOT NULL,verification_progress REAL NOT NULL,initial_block_download INTEGER NOT NULL,tip_time TEXT NOT NULL);
CREATE TABLE observation_bitcoin_block_hash(observation_id TEXT PRIMARY KEY REFERENCES observations(id) ON DELETE CASCADE,height INTEGER NOT NULL,block_hash TEXT NOT NULL);
CREATE TABLE observation_filesystem_capacity(observation_id TEXT PRIMARY KEY REFERENCES observations(id) ON DELETE CASCADE,total_bytes INTEGER NOT NULL,available_bytes INTEGER NOT NULL,read_only INTEGER NOT NULL,mount_present INTEGER NOT NULL);
CREATE TABLE observation_clock_state(observation_id TEXT PRIMARY KEY REFERENCES observations(id) ON DELETE CASCADE,current_time TEXT NOT NULL);
CREATE TABLE observation_electrum_protocol_transport(observation_id TEXT PRIMARY KEY REFERENCES observations(id) ON DELETE CASCADE,reached INTEGER NOT NULL CHECK(reached IN (0,1)),transport_kind TEXT NOT NULL,tls_verification TEXT NOT NULL,protocol_negotiation TEXT NOT NULL,category TEXT NOT NULL);
CREATE TABLE observation_electrum_server_identity(observation_id TEXT PRIMARY KEY REFERENCES observations(id) ON DELETE CASCADE,implementation_family TEXT NOT NULL,protocol_version TEXT NOT NULL);
CREATE TABLE observation_electrum_chain_tip(observation_id TEXT PRIMARY KEY REFERENCES observations(id) ON DELETE CASCADE,height INTEGER NOT NULL,block_hash TEXT NOT NULL,header_time TEXT NOT NULL);
CREATE TABLE findings(id TEXT PRIMARY KEY,scan_id TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,code TEXT NOT NULL,component_id TEXT NOT NULL,status TEXT NOT NULL,applicability TEXT NOT NULL,severity TEXT NOT NULL,confidence TEXT NOT NULL,evaluator_id TEXT NOT NULL,evaluator_version TEXT NOT NULL,evaluated_at TEXT NOT NULL,coverage_role TEXT NOT NULL,UNIQUE(scan_id,id),FOREIGN KEY(scan_id,component_id) REFERENCES components(scan_id,id));
CREATE TABLE finding_unknown_reasons(finding_id TEXT NOT NULL REFERENCES findings(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,code TEXT NOT NULL,stage TEXT NOT NULL,retryability TEXT NOT NULL,resolution_class TEXT NOT NULL,capability_id TEXT NOT NULL,provider_id TEXT NOT NULL,PRIMARY KEY(finding_id,ordinal));
CREATE TABLE finding_evidence(finding_id TEXT NOT NULL REFERENCES findings(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,observation_id TEXT NOT NULL REFERENCES observations(id),observation_kind TEXT NOT NULL,evidence_role TEXT NOT NULL,PRIMARY KEY(finding_id,ordinal));
CREATE TABLE finding_missing_evidence(finding_id TEXT NOT NULL REFERENCES findings(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,observation_kind TEXT NOT NULL,problem TEXT NOT NULL,reason_code TEXT NOT NULL,PRIMARY KEY(finding_id,ordinal));
CREATE TABLE finding_thresholds(finding_id TEXT PRIMARY KEY REFERENCES findings(id) ON DELETE CASCADE,max_tip_age_seconds INTEGER NOT NULL,min_verification_progress REAL NOT NULL,max_header_lag INTEGER NOT NULL,warning_available_percent REAL NOT NULL,failure_available_percent REAL NOT NULL,electrum_tip_warning_age_seconds INTEGER NOT NULL,electrum_tip_failure_age_seconds INTEGER NOT NULL,electrum_lag_warning_blocks INTEGER NOT NULL,electrum_lag_failure_blocks INTEGER NOT NULL,max_observation_skew_seconds INTEGER NOT NULL,max_observation_age_seconds INTEGER NOT NULL,max_future_skew_seconds INTEGER NOT NULL);
CREATE TABLE diagnoses(id TEXT PRIMARY KEY,scan_id TEXT NOT NULL REFERENCES scans(id) ON DELETE CASCADE,code TEXT NOT NULL,classification TEXT NOT NULL,confidence TEXT NOT NULL,summary_key TEXT NOT NULL,correlation_rule_id TEXT NOT NULL,correlation_rule_version TEXT NOT NULL,diagnosed_at TEXT NOT NULL,UNIQUE(scan_id,id));
CREATE TABLE diagnosis_components(diagnosis_id TEXT NOT NULL REFERENCES diagnoses(id) ON DELETE CASCADE,scan_id TEXT NOT NULL,ordinal INTEGER NOT NULL,component_id TEXT NOT NULL,PRIMARY KEY(diagnosis_id,ordinal),FOREIGN KEY(scan_id,diagnosis_id) REFERENCES diagnoses(scan_id,id),FOREIGN KEY(scan_id,component_id) REFERENCES components(scan_id,id));
CREATE TABLE diagnosis_findings(diagnosis_id TEXT NOT NULL REFERENCES diagnoses(id) ON DELETE CASCADE,scan_id TEXT NOT NULL,ordinal INTEGER NOT NULL,finding_id TEXT NOT NULL,PRIMARY KEY(diagnosis_id,ordinal),FOREIGN KEY(scan_id,diagnosis_id) REFERENCES diagnoses(scan_id,id),FOREIGN KEY(scan_id,finding_id) REFERENCES findings(scan_id,id));
CREATE TABLE diagnosis_evidence(diagnosis_id TEXT NOT NULL REFERENCES diagnoses(id) ON DELETE CASCADE,scan_id TEXT NOT NULL,ordinal INTEGER NOT NULL,observation_id TEXT NOT NULL,observation_kind TEXT NOT NULL,evidence_role TEXT NOT NULL,PRIMARY KEY(diagnosis_id,ordinal),FOREIGN KEY(scan_id,diagnosis_id) REFERENCES diagnoses(scan_id,id),FOREIGN KEY(scan_id,observation_id) REFERENCES observations(scan_id,id));
CREATE TABLE diagnosis_blocking_unknowns(diagnosis_id TEXT NOT NULL REFERENCES diagnoses(id) ON DELETE CASCADE,scan_id TEXT NOT NULL,ordinal INTEGER NOT NULL,finding_id TEXT NOT NULL,PRIMARY KEY(diagnosis_id,ordinal),FOREIGN KEY(scan_id,diagnosis_id) REFERENCES diagnoses(scan_id,id),FOREIGN KEY(scan_id,finding_id) REFERENCES findings(scan_id,id));
CREATE TABLE diagnosis_alternatives(diagnosis_id TEXT NOT NULL REFERENCES diagnoses(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,alternative_code TEXT NOT NULL,PRIMARY KEY(diagnosis_id,ordinal));
CREATE INDEX probe_executions_scan_idx ON probe_executions(scan_id);
CREATE INDEX components_scan_idx ON components(scan_id);
CREATE INDEX dependency_edges_scan_idx ON dependency_edges(scan_id);
CREATE INDEX observations_scan_idx ON observations(scan_id);
CREATE INDEX findings_scan_idx ON findings(scan_id);
CREATE INDEX diagnoses_scan_idx ON diagnoses(scan_id);
